"""🖨 Revision print: choose "Questions only" or "With answers" (user 2026-11-11, first in Autonomic Nervous System, then the
pathology modules). Review → Questions → 🖨 Print opens a choice: Questions only = a compact two-column sheet (Name / Student ID /
Date line, options lettered, no answer marks, no explanations — for a paper test, ≈ 9 pages for 133 MCQs instead of 52); With
answers = the existing study sheet (printList, unchanged). The current filters apply to both. Idempotent."""
import sys
R = [
("el('button', { class: 'btn btn-sm', onclick: () => this.printList() }, '🖨 Print')",
 "el('button', { class: 'btn btn-sm', onclick: () => this.printChoice() }, '🖨 Print')"),
('  printList() {\n    const list = this.filtered();',
 '  /** 🖨 Print: choose questions only (compact, for a paper test) or with answers (study sheet). */\n  printChoice() {\n    const n = this.filtered().length;\n    if (!n) { toast(\'No questions match the current filters to print.\', \'warn\'); return; }\n    openModal({ title: \'🖨 Print \' + plural(n, \'question\'),\n      body: el(\'div\', null, el(\'p\', { style: \'margin:0 0 .4rem\' }, \'Choose what to print:\'),\n        el(\'ul\', { class: \'small\', style: \'margin:0\' },\n          el(\'li\', null, el(\'b\', null, \'Questions only\'), \' — compact, two columns, no answers (for a paper test).\'),\n          el(\'li\', null, el(\'b\', null, \'With answers\'), \' — each question with the correct answer marked and its explanation.\'))),\n      actions: [{ label: \'Cancel\' }, { label: \'With answers\', onClick: () => { setTimeout(() => this.printList(), 0); } },\n        { label: \'Questions only\', primary: true, onClick: () => { setTimeout(() => this.printQuestionsOnly(), 0); } }] });\n  },\n  /** Questions only: compact two-column sheet, options lettered, no answer marks or explanations. */\n  printQuestionsOnly() {\n    const list = this.filtered();\n    if (!list.length) { toast(\'No questions match the current filters to print.\', \'warn\'); return; }\n    const out = list.map((q, i) => {\n      let opts = \'\';\n      if (Array.isArray(q.options) && (q.type === \'mcq\' || q.type === \'vignette\' || q.type === \'selectall\')) opts = \'<ol class="qo-opts">\' + q.options.map((o, oi) => \'<li>\' + LETTERS[oi] + \'. \' + esc(o) + \'</li>\').join(\'\') + \'</ol>\';\n      else if (q.type === \'tf\') opts = \'<div class="qo-opts">True / False</div>\';\n      else if (q.type === \'matching\' && Array.isArray(q.pairs)) opts = \'<ol class="qo-opts">\' + q.pairs.map(p => \'<li>\' + esc(p.left) + \' → ______</li>\').join(\'\') + \'</ol>\';\n      else opts = \'<div class="qo-line"></div>\';\n      return \'<div class="qo"><div class="qo-stem"><b>\' + (i + 1) + \'.</b> \' + (q.case ? \'<i>\' + esc(q.case) + \'</i> \' : \'\') + esc(q.stem || \'\') + (q.type === \'selectall\' ? \' <i>(select all that apply)</i>\' : \'\') + \'</div>\' + opts + \'</div>\';\n    }).join(\'\');\n    const f = this.f;\n    const filterBits = [f.topic ? (getTopic(f.topic) ? getTopic(f.topic).title : f.topic) : null, f.type ? TYPE_LABELS[f.type] : null, f.diff ? DIFF_LABELS[f.diff] : null].filter(Boolean);\n    const css = \'html{font-size:12.5px!important}body{line-height:1.3}header.print-head{margin-bottom:.6rem;padding-bottom:.3rem}header.print-head h1{font-size:1.25rem;margin:.1rem 0}\'\n      + \'.qo-wrap{column-count:2;column-gap:1.3rem;column-rule:1px solid #ddd}.qo{break-inside:avoid;page-break-inside:avoid;margin:0 0 .55rem}\'\n      + \'.qo,.qo *{font-size:1rem!important;line-height:1.3!important}.qo-stem{font-weight:600;margin:0 0 .1rem}.qo-opts{list-style:none;margin:0;padding:0 0 0 .9rem}.qo-opts li{margin:0;padding:0}\'\n      + \'.qo-line{border-bottom:1px solid #999;height:1.2rem;margin:0 0 0 .9rem}.qo-name{font-family:Arial,sans-serif;font-size:.9rem;margin:0 0 .6rem}\';\n    printHTML(\'Revision — Questions\', plural(list.length, \'question\') + (filterBits.length ? \' · \' + filterBits.join(\' · \') : \' · all topics\') + \' · questions only\',\n      \'<div class="qo-name">Name: ____________________ &nbsp; Student ID: ______________ &nbsp; Date: __________</div><div class="qo-wrap">\' + out + \'</div>\', { css });\n  },\n  printList() {\n    const list = this.filtered();'),
]
for path in sys.argv[1:]:
    s = open(path, encoding='utf-8').read(); n = 0
    for a, b in R:
        if b in s: continue
        assert s.count(a) == 1, (path, a[:70]); s = s.replace(a, b); n += 1
    open(path, 'w', encoding='utf-8').write(s); print(path, 'changes:', n)
